definition.script:
String normalizeBranchSpec(String branch)
{
    String value = branch?.trim()
    if (!value) {
        return '*/main'
    }

    value = value.replaceFirst('^refs/heads/', '')
    value = value.replaceFirst('^origin/', '')
    return value.startsWith('*/') ? value : "*/${value}"
}

String readProjectAppVersion(String projectSettings)
{
    def lines = projectSettings.readLines().findAll { it.startsWith('  bundleVersion:') }
    if (lines.size() != 1) {
        error('ProjectSettings/ProjectSettings.asset must contain exactly one PlayerSettings bundleVersion.')
    }
    String version = lines[0].split(':', 2)[1].trim()
    if (version.length() >= 2 && ((version.startsWith('"') && version.endsWith('"')) ||
        (version.startsWith("'") && version.endsWith("'")))) {
        version = version.substring(1, version.length() - 1)
    }
    if (!(version ==~ /^[0-9]+([.][0-9]+){0,2}$/)) {
        error("Unity Player Settings Version must contain one to three numeric components: ${version}")
    }
    return version
}

pipeline {
    agent {
        node {
            label 'built-in'
        }
    }

    options {
        skipDefaultCheckout(true)
        disableConcurrentBuilds()
        lock(resource: 'headsling-unity-macos')
        buildDiscarder(logRotator(numToKeepStr: '10'))
        timeout(time: 240, unit: 'MINUTES')
        timestamps()
    }

    parameters {
        choice(name: 'SOURCE_MODE', choices: ['LOCAL_SNAPSHOT', 'GIT'], description: 'Local snapshot includes saved, unpushed source changes; Git builds the selected branch.')
        string(name: 'LOCAL_SOURCE_PATH', defaultValue: '/Users/daisei/HeadGame', description: 'Read-only source for LOCAL_SNAPSHOT. Caches and credentials are excluded.')
        string(name: 'BRANCH', defaultValue: 'main', description: 'Git branch for GIT mode. The branch must use the dedicated HEADSLING asset bucket.')
        choice(name: 'UNITY_VERSION', choices: ['6000.5.1f1'], description: 'Unity version; must match ProjectVersion.txt.')
        booleanParam(name: 'CLEAN_LIBRARY', defaultValue: false, description: 'Delete the Unity Library cache before building.')
        booleanParam(name: 'UPLOAD_APP_STORE', defaultValue: true, description: 'Validate and upload the IPA to App Store Connect.')
    }

    environment {
        HEADSLING_BUILD_TARGET = 'iOS'
        UNITY_BUILD_METHOD = 'HeadSling.Editor.HeadSlingMobileBuilder.BuildIOS'
        APPLE_TEAM_ID = 'S88E744TXJ'
        APP_BUNDLE_ID = 'com.headsling.prototype'
        XCODE_OUTPUT_PATH = 'Builds/iOS'
        ARCHIVE_PATH = 'Builds/iOSArchive/HEADSLING.xcarchive'
        IPA_OUTPUT_PATH = 'Builds/iOSIPA'
        DERIVED_DATA_PATH = 'Builds/iOSDerivedData'
        EXPORT_OPTIONS_PATH = 'Builds/iOSExportOptions.plist'
    }

    stages {
        stage('Checkout') {
            steps {
                script {
                    env.HEADSLING_SOURCE_MODE = params.SOURCE_MODE ?: 'LOCAL_SNAPSHOT'
                    env.HEADSLING_SOURCE_PROJECT = params.LOCAL_SOURCE_PATH?.trim() ?: '/Users/daisei/HeadGame'
                    env.HEADSLING_BRANCH = normalizeBranchSpec(params.BRANCH?.toString())
                    if (!(env.HEADSLING_SOURCE_MODE in ['LOCAL_SNAPSHOT', 'GIT'])) {
                        error('SOURCE_MODE must be LOCAL_SNAPSHOT or GIT.')
                    }
                    if (env.HEADSLING_SOURCE_MODE == 'LOCAL_SNAPSHOT') {
                        sh '''#!/bin/bash
set -euo pipefail
test -f "$HEADSLING_SOURCE_PROJECT/tools/ci/prepare-solo-workspace.py"
# The helper only writes the distinct Jenkins WORKSPACE and never the source.
# Preserve this job's Library here; CLEAN_LIBRARY remains in Preflight.
python3 "$HEADSLING_SOURCE_PROJECT/tools/ci/prepare-solo-workspace.py" \
  --source "$HEADSLING_SOURCE_PROJECT" --workspace "$WORKSPACE" --preserve-library
'''
                    } else {
                        checkout([
                            $class: 'GitSCM',
                            branches: [[name: env.HEADSLING_BRANCH]],
                            doGenerateSubmoduleConfigurations: false,
                            extensions: [[$class: 'LocalBranch', localBranch: '**']],
                            userRemoteConfigs: [[
                                credentialsId: 'bodacheng',
                                url: 'https://github.com/bodacheng/HeadGame.git'
                            ]]
                        ])
                        sh '''#!/bin/bash
set -euo pipefail
test -f tools/ci/prepare-solo-workspace.py
# Remove any source left by an earlier local snapshot; retain ignored caches.
git reset --hard HEAD >/dev/null
git clean -fd >/dev/null
rm -rf "$WORKSPACE/Logs/Jenkins"
python3 tools/ci/prepare-solo-workspace.py --source "$WORKSPACE" --inspect-only
'''
                    }
                    env.HEADSLING_GIT_REVISION = sh(returnStdout: true, script: '''#!/bin/bash
set -euo pipefail
python3 - <<'PY'
import json, os, re
with open('Logs/Jenkins/source-snapshot.json', encoding='utf-8') as stream:
    receipt = json.load(stream)
revision = receipt.get('sourceGitRevision')
dirty = receipt.get('sourceDirty')
dirty_hash = receipt.get('sourceDirtyHash')
if not isinstance(revision, str) or not re.fullmatch(r'[0-9a-f]{40}|[0-9a-f]{64}', revision):
    raise SystemExit('Invalid source Git revision in receipt.')
if type(dirty) is not bool or (dirty and (not isinstance(dirty_hash, str) or not re.fullmatch(r'[0-9a-f]{64}', dirty_hash))):
    raise SystemExit('Invalid source dirty fingerprint in receipt.')
if os.environ['HEADSLING_SOURCE_MODE'] == 'GIT' and dirty:
    raise SystemExit('Git source must be clean; refusing mixed source from an earlier workspace run.')
print(revision + (':dirty:' + dirty_hash if dirty else ''))
PY
''').trim()
                }
            }
        }

        stage('Preflight') {
            steps {
                script {
                    def requiredBuildFiles = ['Assets/Editor/HeadSlingCIBuild.cs', 'tools/ci/verify-addressables.py', 'tools/ci/prepare-ios-signing.py', 'Assets/Resources/HeadSling/solo-content-settings.json']
                    if (params.UPLOAD_APP_STORE) {
                        requiredBuildFiles.add('tools/ci/check-online-backend.py')
                    }
                    def missingBuildFiles = requiredBuildFiles.findAll { !fileExists(it) }
                    if (missingBuildFiles) {
                        error("Branch ${env.HEADSLING_BRANCH} is missing CI build files: ${missingBuildFiles.join(', ')}. Merge the mobile pipeline changes into that branch before building.")
                    }
                    env.HEADSLING_APP_VERSION = readProjectAppVersion(readFile('ProjectSettings/ProjectSettings.asset'))
                    String projectUnityVersion = readFile('ProjectSettings/ProjectVersion.txt')
                        .readLines()
                        .find { it.startsWith('m_EditorVersion:') }
                        ?.split(':', 2)?.last()?.trim()
                    env.HEADSLING_UNITY_VERSION = params.UNITY_VERSION?.toString()?.trim() ?: projectUnityVersion
                    if (!env.HEADSLING_UNITY_VERSION) {
                        error('Unable to resolve a Unity version.')
                    }
                    if (projectUnityVersion && projectUnityVersion != env.HEADSLING_UNITY_VERSION) {
                        error("Project requires Unity ${projectUnityVersion}; selected ${env.HEADSLING_UNITY_VERSION}.")
                    }
                    env.HEADSLING_CI_RUN_ID = env.BUILD_TAG
                    currentBuild.description = "Version: ${env.HEADSLING_APP_VERSION}\nBuild: ${env.BUILD_NUMBER}\nSource: ${env.HEADSLING_SOURCE_MODE}\nBranch: ${env.HEADSLING_BRANCH}\nUnity: ${env.HEADSLING_UNITY_VERSION}\nGit: ${env.HEADSLING_GIT_REVISION}"
                }
                sh '''#!/bin/bash
set -euo pipefail

UNITY_EXECUTABLE="/Applications/Unity/Hub/Editor/${HEADSLING_UNITY_VERSION}/Unity.app/Contents/MacOS/Unity"
if [ ! -x "$UNITY_EXECUTABLE" ]; then
    echo "Unity executable not found: $UNITY_EXECUTABLE" >&2
    exit 2
fi

test -d "/Applications/Unity/Hub/Editor/${HEADSLING_UNITY_VERSION}/PlaybackEngines/iOSSupport"
command -v python3 >/dev/null

# Both source modes must embed the newly dedicated bucket. In particular, a
# future Git build must not silently use an older branch with the shared bucket.
python3 - <<'PY'
import json
with open('Assets/Resources/HeadSling/solo-content-settings.json', encoding='utf-8') as stream:
    settings = json.load(stream)
expected = 'https://headsling-assets-664894817585.s3.ap-northeast-1.amazonaws.com/release/headsling/config/v1'
if settings.get('RemoteCatalogRoot') != expected:
    raise SystemExit('Source must use the dedicated HEADSLING bucket RemoteCatalogRoot: ' + expected)
PY

if [ "$CLEAN_LIBRARY" = "true" ]; then
    rm -rf "$WORKSPACE/Library"
fi

# Keep the provenance receipt produced by Checkout while clearing old logs.
if [ -d "$WORKSPACE/Logs/Jenkins" ]; then
    find "$WORKSPACE/Logs/Jenkins" -mindepth 1 -maxdepth 1 ! -name source-snapshot.json -exec rm -rf {} +
fi
rm -rf "$WORKSPACE/$XCODE_OUTPUT_PATH" "$WORKSPACE/$ARCHIVE_PATH" \
       "$WORKSPACE/$IPA_OUTPUT_PATH" "$WORKSPACE/$DERIVED_DATA_PATH"
mkdir -p "$WORKSPACE/Logs/Jenkins" "$WORKSPACE/$(dirname "$ARCHIVE_PATH")" \
         "$WORKSPACE/$IPA_OUTPUT_PATH" "$WORKSPACE/$DERIVED_DATA_PATH"

# Published clients must be able to load accounts on the deployed backend.
if [ "$UPLOAD_APP_STORE" = "true" ]; then
    python3 tools/ci/check-online-backend.py --timeout 30 \
      --report Logs/Jenkins/online-backend-preflight.json
fi

echo "Branch $HEADSLING_BRANCH"
echo "Git $HEADSLING_GIT_REVISION"
echo "Unity $HEADSLING_UNITY_VERSION"
echo "App version $HEADSLING_APP_VERSION (Unity Player Settings)"
xcodebuild -version
security find-identity -v -p codesigning
'''
            }
        }

        stage('Build Addressables (iOS)') {
            steps {
                sh '''#!/bin/bash
set -euo pipefail
UNITY_EXECUTABLE="/Applications/Unity/Hub/Editor/${HEADSLING_UNITY_VERSION}/Unity.app/Contents/MacOS/Unity"
"$UNITY_EXECUTABLE" -projectPath "$WORKSPACE" -quit -batchmode -nographics \
  -buildTarget iOS -executeMethod HeadSling.Editor.HeadSlingCIBuild.BuildAddressables \
  -logFile "$WORKSPACE/Logs/Jenkins/addressables_ios_${BUILD_NUMBER}.log"
test -s "$WORKSPACE/Logs/Jenkins/addressables-iOS.json"
'''
            }
        }

        stage('Unity Export') {
            steps {
                sh '''#!/bin/bash
set -euo pipefail

UNITY_EXECUTABLE="/Applications/Unity/Hub/Editor/${HEADSLING_UNITY_VERSION}/Unity.app/Contents/MacOS/Unity"

HEADSLING_PREBUILT_ADDRESSABLES=true \
HEADSLING_BUNDLE_ID="$APP_BUNDLE_ID" \
HEADSLING_BUILD_NUMBER="$BUILD_NUMBER" \
"$UNITY_EXECUTABLE" \
  -projectPath "$WORKSPACE" \
  -quit \
  -batchmode \
  -nographics \
  -buildTarget iOS \
  -executeMethod "$UNITY_BUILD_METHOD" \
  -logFile "$WORKSPACE/Logs/Jenkins/ios_${BUILD_NUMBER}.log"

python3 tools/ci/verify-addressables.py Logs/Jenkins/addressables-iOS.json "$XCODE_OUTPUT_PATH" \
  --output Logs/Jenkins/addressables-ios-export-check.json

# HEADSLING only uses the operating system's exempt HTTPS/TLS encryption.
# Embedding the declaration prevents App Store Connect from asking for export
# compliance information again for every uploaded build.
APP_INFO_PLIST="$WORKSPACE/$XCODE_OUTPUT_PATH/Info.plist"
/usr/libexec/PlistBuddy -c "Add :ITSAppUsesNonExemptEncryption bool false" "$APP_INFO_PLIST" 2>/dev/null || \
  /usr/libexec/PlistBuddy -c "Set :ITSAppUsesNonExemptEncryption false" "$APP_INFO_PLIST"
'''
            }
        }

        stage('Prepare iOS Signing') {
            steps {
                withCredentials([
                    string(credentialsId: 'PCUSER_PASSWORD', variable: 'KEYCHAIN_PASSWORD'),
                    string(credentialsId: 'HEADSLING_ASC_KEY_ID', variable: 'API_KEY'),
                    string(credentialsId: 'HEADSLING_ASC_ISSUER_ID', variable: 'API_ISSUER')
                ]) {
                    sh '''#!/bin/bash
set -euo pipefail
KEYCHAIN="$HOME/Library/Keychains/login.keychain-db"
security unlock-keychain -p "$KEYCHAIN_PASSWORD" "$KEYCHAIN"
security set-keychain-settings -lut 21600 "$KEYCHAIN"
python3 tools/ci/prepare-ios-signing.py
'''
                }
            }
        }

        stage('Xcode Archive') {
            steps {
                withCredentials([
                    string(credentialsId: 'HEADSLING_ASC_KEY_ID', variable: 'API_KEY'),
                    string(credentialsId: 'HEADSLING_ASC_ISSUER_ID', variable: 'API_ISSUER')
                ]) {
                    sh '''#!/bin/bash
set -euo pipefail

PRIVATE_KEY="$HOME/.appstoreconnect/private_keys/AuthKey_${API_KEY}.p8"
test -f "$PRIVATE_KEY"

cd "$WORKSPACE/$XCODE_OUTPUT_PATH"
if [ -d "Unity-iPhone.xcworkspace" ]; then
    CONTAINER_ARGS=( -workspace "Unity-iPhone.xcworkspace" )
elif [ -d "Unity-iPhone.xcodeproj" ]; then
    CONTAINER_ARGS=( -project "Unity-iPhone.xcodeproj" )
else
    echo "Unity-iPhone Xcode project was not generated." >&2
    exit 3
fi

xcodebuild "${CONTAINER_ARGS[@]}" \
  -allowProvisioningUpdates \
  -authenticationKeyPath "$PRIVATE_KEY" \
  -authenticationKeyID "$API_KEY" \
  -authenticationKeyIssuerID "$API_ISSUER" \
  -scheme Unity-iPhone \
  -configuration Release \
  -destination 'generic/platform=iOS' \
  -archivePath "$WORKSPACE/$ARCHIVE_PATH" \
  -derivedDataPath "$WORKSPACE/$DERIVED_DATA_PATH" \
  archive \
  CODE_SIGN_STYLE=Automatic \
  DEVELOPMENT_TEAM="$APPLE_TEAM_ID" \
  MARKETING_VERSION="$HEADSLING_APP_VERSION" \
  CURRENT_PROJECT_VERSION="$BUILD_NUMBER"
'''
                }
            }
        }

        stage('Export IPA') {
            steps {
                sh '''#!/bin/bash
set -euo pipefail
xcodebuild -exportArchive \
  -archivePath "$WORKSPACE/$ARCHIVE_PATH" \
  -exportPath "$WORKSPACE/$IPA_OUTPUT_PATH" \
  -exportOptionsPlist "$WORKSPACE/$EXPORT_OPTIONS_PATH"
IPA_FILE="$(find "$WORKSPACE/$IPA_OUTPUT_PATH" -maxdepth 1 -type f -name '*.ipa' -print -quit)"
test -n "$IPA_FILE"
python3 tools/ci/verify-addressables.py Logs/Jenkins/addressables-iOS.json "$IPA_FILE" \
  --output Logs/Jenkins/addressables-ios-ipa-check.json
'''
            }
        }

        stage('Archive IPA') {
            steps {
                archiveArtifacts(
                    artifacts: 'Builds/iOSIPA/*.ipa',
                    fingerprint: true,
                    followSymlinks: false
                )
            }
        }

        stage('Upload App Store') {
            when {
                expression { return params.UPLOAD_APP_STORE }
            }
            steps {
                withCredentials([
                    string(credentialsId: 'HEADSLING_ASC_KEY_ID', variable: 'API_KEY'),
                    string(credentialsId: 'HEADSLING_ASC_ISSUER_ID', variable: 'API_ISSUER')
                ]) {
                    sh '''#!/bin/bash
set -euo pipefail

python3 tools/ci/check-online-backend.py --timeout 30 \
  --report Logs/Jenkins/online-backend-upload.json

PRIVATE_KEY="$HOME/.appstoreconnect/private_keys/AuthKey_${API_KEY}.p8"
if [ ! -f "$PRIVATE_KEY" ]; then
    echo "App Store Connect private key is missing: ~/.appstoreconnect/private_keys/AuthKey_<key-id>.p8" >&2
    exit 4
fi

IPA_FILE="$(find "$WORKSPACE/$IPA_OUTPUT_PATH" -maxdepth 1 -type f -name '*.ipa' -print -quit)"
xcrun altool --validate-app -f "$IPA_FILE" -t ios --apiKey "$API_KEY" --apiIssuer "$API_ISSUER"
xcrun altool --upload-app -f "$IPA_FILE" -t ios --apiKey "$API_KEY" --apiIssuer "$API_ISSUER"
'''
                }
            }
        }
    }

    post {
        always {
            archiveArtifacts(
                allowEmptyArchive: true,
                artifacts: "Logs/Jenkins/**, Logs/iOSBuildSummary.txt, Assets/AddressableAssetsData/iOS/addressables_content_state.bin, Builds/iOSExportOptions.plist, Builds/iOSIPA/*.ipa",
                fingerprint: true,
                followSymlinks: false
            )
        }
    }
}
